// Priority-speaker ducking. Applied by the node to server-mixed and native per-participant
// delivery (after the receiver's own mute/volume/block and positional attenuation, before
// ambient/`max_streams` ranking); receivers of dedicated WebRTC tracks apply the same envelope
// locally. Several simultaneous priority speakers keep the duck engaged; priority streams are
// never attenuated.
type DuckingConfig struct {
	// Gain applied to every non-priority stream while a priority speaker is audible (`0` mutes them).
	Gain *float64 `json:"gain,omitempty"`
	// Ramp from full gain down to `gain`.
	AttackMs *int64 `json:"attack_ms,omitempty"`
	// Ramp back to full gain once the hold expires.
	ReleaseMs *int64 `json:"release_ms,omitempty"`
	// How long ducking stays fully engaged after the last priority speaker goes silent.
	HoldMs *int64 `json:"hold_ms,omitempty"`
	// Members with role `moderator`/`administrator` count as priority speakers too (explicit
	// `priority` grants always do).
	Moderators *bool `json:"moderators,omitempty"`
}

