// Sums of additive counters and maxima of peaks over a range.
type FleetUsageAppsItem struct {
	// Highest number of concurrently connected sessions (CCU) in any bucket
	PeakSessions int64 `json:"peak_sessions"`
	// Connected session time, clipped to the range
	SessionMinutes  float64 `json:"session_minutes"`
	SessionsStarted int64   `json:"sessions_started"`
	// Highest number of concurrent channel memberships
	PeakParticipants int64 `json:"peak_participants"`
	// Channel membership time (a user in two channels counts twice); this is what the monthly quota
	// meters
	ParticipantMinutes float64 `json:"participant_minutes"`
	RecordingSeconds   float64 `json:"recording_seconds"`
	// AURX/WebRTC media bytes received from the application's players
	MediaBytesIn int64 `json:"media_bytes_in"`
	// Media bytes sent to the application's players
	MediaBytesOut int64 `json:"media_bytes_out"`
	ChatMessages  int64 `json:"chat_messages"`
	TTSRequests   int64 `json:"tts_requests"`
	TTSCharacters int64 `json:"tts_characters"`
	// Audio milliseconds submitted to the STT provider
	STTAudioMs int64 `json:"stt_audio_ms"`
	// Per-session quality ratings taken in the bucket
	QualitySamples int64 `json:"quality_samples"`
	// Sum of MOS × 1000 over the ratings (`/ quality_samples / 1000` = mean MOS)
	MOSSumMilli int64 `json:"mos_sum_milli"`
	RTTSumMs    int64 `json:"rtt_sum_ms"`
	// Sum of the worse direction's jitter
	JitterSumMs int64 `json:"jitter_sum_ms"`
	// Sum of the worse direction's loss × 10
	LossSumPermille int64 `json:"loss_sum_permille"`
	// Ratings at 1–2 bars
	PoorQualitySamples int64 `json:"poor_quality_samples"`
	// Derived from the `quality_*` counters
	Quality QualityAggregate `json:"quality"`
	AppID   string           `json:"app_id"`
}

