// The least-loaded healthy node of one region that advertises a public WebSocket URL
// (`server.external_ws_url`). Connect the SDK to `ws_url`; `GET probe_url` is a cheap public
// request answered by exactly this node, so its round-trip time is a fair RTT estimate.
type RegionEndpoint struct {
	Region Region `json:"region"`
	NodeID string `json:"node_id"`
	// WebSocket control-plane URL of the node (`wss://…/ws`). Session resume must reach the same node,
	// so this is a per-node URL, not a load balancer.
	WSURL string `json:"ws_url"`
	// `<api_url>/health` of the node, for client-side RTT measurement.
	ProbeURL *string      `json:"probe_url,omitempty"`
	Location *GeoLocation `json:"location,omitempty"`
	// Great-circle distance from the caller's declared location, when both are known.
	DistanceKm *float64 `json:"distance_km,omitempty"`
	// Healthy, non-saturated nodes advertising a WebSocket URL in this region.
	Nodes int64 `json:"nodes"`
	// `active_participants / capacity` of the selected node (0–1).
	LoadFactor float64 `json:"load_factor"`
}

// RegionsResponse is the `RegionsResponse` schema.
type RegionsResponse struct {
	// Best-first: the preferred region if it has capacity, then by distance to the declared location
	// (regions without coordinates last), then by load. Clients that can measure RTT should probe
	// every `probe_url` and pick the lowest; this order is the fallback.
	Regions []RegionEndpoint `json:"regions"`
	// First entry of `regions`, or `null` when no node advertises a WebSocket URL.
	Recommended *RegionEndpoint `json:"recommended"`
}

